import React from 'react';

const Home = () => {
    const sectionStyle = {
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        height: '100vh',
        backgroundColor: '#f0f8ff',
        fontFamily: 'Arial, sans-serif',
        textAlign: 'center',
        padding: '2rem',
    };

    const headingStyle = {
        fontSize: '3rem',
        color: '#333',
        marginBottom: '1rem',
    };

    const paragraphStyle = {
        fontSize: '1.5rem',
        color: '#555',
        maxWidth: '600px',
        lineHeight: '1.8',
    };

    const buttonStyle = {
        marginTop: '2rem',
        padding: '0.8rem 2rem',
        fontSize: '1rem',
        color: '#fff',
        backgroundColor: '#007bff',
        border: 'none',
        borderRadius: '5px',
        cursor: 'pointer',
        textDecoration: 'none',
    };

    const buttonHoverStyle = {
        backgroundColor: '#0056b3',
    };

    return (
        <section style={sectionStyle}>
            <h1 style={headingStyle}>Welcome to My Profile</h1>
            <p style={paragraphStyle}>
                Hello! I'm <strong>Duclayan, Krizstian Marco G.</strong>, a 3IT-B student. Explore my profile to know more about me!
            </p>
            <a
                href="#about"
                style={buttonStyle}
                onMouseOver={(e) => (e.target.style.backgroundColor = buttonHoverStyle.backgroundColor)}
                onMouseOut={(e) => (e.target.style.backgroundColor = buttonStyle.backgroundColor)}
            >
                Learn More About Me
            </a>
        </section>
    );
};

export default Home;
